import {
  addDays,
  addWeeks,
  compareAsc,
  eachDayOfInterval,
  endOfMonth,
  isEqual,
  startOfWeek,
  endOfWeek,
  endOfDay,
  isSameDay,
  intervalToDuration,
  isWithinInterval,
  startOfDay,
  isBefore,
  isAfter,
} from 'date-fns';

import type { TimeValue, TimeframeV2 } from '../../../../core/types/time.js';
import {
  _sortTimeframeV2Values,
  _getTimeValueFromSimpleValue,
} from '../../../forms-core/time/helpers.js';
import {
  _isTimeframeV2,
  _StringTimeOffset,
} from '../../../forms-core/time/types.js';
import type { _CalendarValueType, _CalendarType } from '../Calendar.js';
import type { ViewItem } from '../CalendarItem.js';
import type { _Day } from '../hooks/useSelectDay.js';
import {
  NUMBER_OF_WEEK_ROWS,
  NUMBER_OF_WEEKDAYS,
} from '../types/calendarConfiguration.js';
import type { FirstDayOfWeek, _CalendarState } from '../types/shared-types.js';

/** Get days to render in the select date view. */
export function getDays(
  activeDate: Date,
  weekStartsOn: FirstDayOfWeek,
): _Day[] {
  const monthStart = new Date(activeDate.getFullYear(), activeDate.getMonth());
  const firstWeekStart = startOfWeek(monthStart, {
    weekStartsOn,
  });
  const monthEnd = endOfMonth(monthStart);
  const lastWeekEnd = endOfWeek(monthEnd, { weekStartsOn });

  // Get days of previous month to fill empty spots of the date grid
  let prevMonthDays = getSiblingMonthDays(monthStart, firstWeekStart, -1);

  const currentMonthDays = toDayArray(
    eachDayOfInterval({
      start: monthStart,
      end: monthEnd,
    }),
    true,
  );

  // Get days of next month to fill empty spots of the date grid
  const nextMonthDays = getSiblingMonthDays(monthEnd, lastWeekEnd, 1);

  const days = [...prevMonthDays, ...currentMonthDays, ...nextMonthDays];

  // Depending on the start/end day of the month, we might need additional rows
  // to fill up all the empty spaces of the date grid
  while (days.length < NUMBER_OF_WEEKDAYS * NUMBER_OF_WEEK_ROWS) {
    if (!prevMonthDays.length) {
      // Add additional row of sibling month days before the current month
      prevMonthDays = toDayArray(
        eachDayOfInterval({
          start: addWeeks(firstWeekStart, -1),
          end: addDays(firstWeekStart, -1),
        }),
      );

      days.unshift(...prevMonthDays);
    } else {
      // Add additional row of sibling month days after the current month
      days.push(
        ...toDayArray(
          eachDayOfInterval({
            start: addDays(lastWeekEnd, 1),
            end: addWeeks(lastWeekEnd, 1),
          }),
        ),
      );
    }
  }

  return days;
}

/** Get previous or next month's days to fill the current date select view with the fixed number of rows. */
function getSiblingMonthDays(
  monthStartEnd: Date,
  weekStartEnd: Date,
  direction: 1 | -1,
): _Day[] {
  // No need to fill empty spots if month start and week start are equal
  if (isEqual(monthStartEnd, weekStartEnd)) {
    return [];
  }

  // Get first/last day of sibling month
  const siblingMonthStartEnd = addDays(monthStartEnd, direction);

  // eachDayOfInterval throws an error if the range start and end are equal
  // Return just one day if month start/end is equal to week start/end
  if (isEqual(siblingMonthStartEnd, weekStartEnd)) {
    return [{ date: weekStartEnd, isCurrentMonthDay: false }];
  }

  // The range start date must be prior to the range end date -> sort dates
  const sortedDays = [siblingMonthStartEnd, weekStartEnd].sort((a, b) =>
    compareAsc(a, b),
  );

  // Return array with days to fill up the empty spots of the currently displayed month
  return toDayArray(
    eachDayOfInterval({
      start: sortedDays[0],
      end: sortedDays[1],
    }),
  );
}

/** Map array of dates to an array of Day objects */
function toDayArray(
  array: Date[],
  isCurrentMonthDay: boolean | undefined = false,
): _Day[] {
  return array.map((date): _Day => {
    return { date, isCurrentMonthDay };
  });
}

/**
 * Tries to convert the given value to the proper TimeValue / TimeframeV2 structure. If not possible it returns null.
 * @internal
 */
export function _convertToCalendarStructure<Type extends _CalendarType>(
  type: _CalendarType = 'single',
  timeOffset: _StringTimeOffset,
  value?: _CalendarValueType<Type>,
): TimeValue | Partial<TimeframeV2> | null {
  if (_isTimeframeV2(value, type)) {
    if (value) {
      const from = _getTimeValueFromSimpleValue(value.from?.value, timeOffset);
      const to = _getTimeValueFromSimpleValue(value.to?.value, timeOffset);
      return _sortTimeframeV2Values({ from, to });
    }
    return { from: undefined, to: undefined };
  }

  return _getTimeValueFromSimpleValue(value, timeOffset) ?? null;
}

/** @internal */
function _getRangePosition(newDate: Date, from: Date, to: Date) {
  if (from && isSameDay(newDate, from)) {
    return 'first';
  }

  if (to && isSameDay(newDate, to)) {
    return 'last';
  }

  if (
    isWithinInterval(newDate, {
      start: startOfDay(from),
      end: endOfDay(to),
    })
  ) {
    return 'inbetween';
  }
}

function _isRelativeDate(
  highlightType: ViewItem['highlightType'],
  selectedDate: Partial<TimeframeV2>,
): ViewItem['selectionVariant'] {
  switch (highlightType) {
    case 'first': {
      if (selectedDate.from) {
        return selectedDate.from.type === 'iso8601' ? 'absolute' : 'relative';
      }
      return undefined;
    }
    case 'last': {
      if (selectedDate.to) {
        return selectedDate.to.type === 'iso8601' ? 'absolute' : 'relative';
      }
      // if the to is selected first, an earlier date should become the from in the end, therefore
      if (!selectedDate.to && selectedDate.from) {
        return selectedDate.from.type === 'iso8601' ? 'absolute' : 'relative';
      }

      return undefined;
    }
    case 'same': {
      if (
        selectedDate.from?.type === 'expression' &&
        selectedDate.to?.type === 'expression'
      ) {
        return 'relative';
      }

      if (
        selectedDate.from?.type === 'expression' &&
        selectedDate.to?.type === 'iso8601'
      ) {
        return 'relative-absolute';
      }

      if (
        selectedDate.from?.type === 'iso8601' &&
        selectedDate.to?.type === 'expression'
      ) {
        return 'absolute-relative';
      }

      return 'absolute';
    }
    case 'inbetween':
    default: {
      return undefined;
    }
  }
}

/** @internal */
function _getHighlightType(
  from: Date | undefined | null,
  to: Date | undefined | null,
  newDate: Date,
) {
  if (
    (to && from && isSameDay(from, newDate) && isSameDay(to, newDate)) ||
    (!to && from && isSameDay(from, newDate)) ||
    (!from && to && isSameDay(to, newDate))
  ) {
    return 'same';
  }

  if (from && to && isBefore(from, to)) {
    return _getRangePosition(newDate, from, to);
  }

  if (from && to && isBefore(to, from)) {
    return _getRangePosition(newDate, to, from);
  }

  return undefined;
}

/** @internal */
export function _isCompleteSelection(
  type: 'single' | 'range',
  selectedDate?: Partial<TimeframeV2> | TimeframeV2 | TimeValue | null,
) {
  return _isTimeframeV2(selectedDate, type)
    ? !!(selectedDate.from && selectedDate.to)
    : !!selectedDate?.value;
}

/**
 * Checks if the passed date is the selected date or part of the selected date range.
 * Depending on the selection it defines the highlightColor, the highlightType and if it is a relative timeframe.
 * @internal
 */
export const _getHighlightingProps = (
  date: Date,
  state: Pick<_CalendarState, 'hoveredDate' | 'selectedDate' | 'type'>,
): Pick<
  ViewItem,
  'isSelected' | 'highlightColor' | 'highlightType' | 'selectionVariant'
> => {
  const { selectedDate, hoveredDate, type } = state;
  if (!selectedDate) {
    return {};
  }

  if (_isTimeframeV2(selectedDate, type)) {
    const { from: selectedFrom, to: selectedTo } = selectedDate;
    if (!selectedFrom && !selectedTo) {
      return {};
    }

    const selectedFromDate = selectedFrom
      ? new Date(selectedFrom.absoluteDate)
      : null;
    const selectedToDate = selectedTo
      ? new Date(selectedTo.absoluteDate)
      : null;

    const isSelected = !!(
      (selectedFromDate && isSameDay(date, selectedFromDate)) ||
      (selectedToDate && isSameDay(date, selectedToDate))
    );

    const safeFromDate = selectedFromDate ?? hoveredDate;
    const safeToDate = selectedToDate ?? hoveredDate;

    const highlightType = _getHighlightType(safeFromDate, safeToDate, date);
    const isEntireRangeSelected = selectedFrom && selectedTo && highlightType;

    const highlightColor =
      isSelected || isEntireRangeSelected ? 'primary' : 'neutral';

    const isRelative = isSelected
      ? _isRelativeDate(highlightType, selectedDate)
      : undefined;

    return {
      highlightType,
      highlightColor,
      isSelected,
      selectionVariant: isRelative,
    };
  }

  const isSelected = isSameDay(date, new Date(selectedDate.absoluteDate));

  if (isSelected) {
    return {
      isSelected: true,
      highlightType: 'same',
      highlightColor: 'primary',
      selectionVariant:
        selectedDate.type === 'expression' ? 'relative' : 'absolute',
    };
  }

  return {
    isSelected: false,
  };
};

/** @internal */
export function _isOutOfBounds(ISODate?: string, min?: Date, max?: Date) {
  if (!ISODate) {
    return false;
  }
  const date = new Date(ISODate);

  if (min && max) {
    return isBefore(date, min) || isAfter(date, max);
  }

  if (min && !max) {
    return isBefore(date, min);
  }

  if (!min && max) {
    return isAfter(date, max);
  }

  return false;
}

/**
 * Returns the number of days from the start of the week until the current date.
 * @internal
 */
export function _getWeekStartOrEnd(
  indicator: 'startOfWeek' | 'endOfWeek',
  activeDate: Date,
  weekStartsOn: FirstDayOfWeek,
) {
  const start =
    indicator === 'startOfWeek'
      ? startOfWeek(activeDate, { weekStartsOn })
      : endOfWeek(activeDate, { weekStartsOn });

  return (
    (intervalToDuration({
      start,
      end: activeDate,
    }).days ?? 0) * (indicator === 'startOfWeek' ? -1 : 1)
  );
}

/**
 * Returns the next position depending on the current.
 * @internal
 */
export function _getPosition(
  position?: _CalendarState['position'],
  value?: TimeValue | Partial<TimeframeV2> | TimeframeV2 | null,
) {
  // single selection
  if (!position) {
    return undefined;
  }

  // If there is no position it always is a range selection
  if (
    _isCompleteSelection('range', value) ||
    value === null ||
    (!(value as Partial<TimeframeV2>).from?.value &&
      !(value as Partial<TimeframeV2>).to?.value)
  ) {
    return 'from';
  }

  return position === 'from' ? 'to' : 'from';
}

/**
 * Either assigns and sanitizes the passed timeValue to the Timeframe or returns the TimeValue in case of single selection.
 * @internal
 */
export function _getDateFromSelection(
  oldSelection: TimeValue | Partial<TimeframeV2> | null,
  type: _CalendarType,
  timeValue?: TimeValue,
  position?: _CalendarState['position'],
) {
  if (_isTimeframeV2(oldSelection, type)) {
    const tmp = oldSelection ? { ...oldSelection } : {};
    tmp[position ?? 'from'] = timeValue;
    // Clears the to date in case a new selection starts.
    if (position === 'from') {
      tmp['to'] = undefined;
    }

    return _sortTimeframeV2Values(tmp);
  }

  return timeValue ?? null;
}
